"""Local dictionary tables, aligned with the existing mirror builder."""
SCHEMA = '\nCREATE TABLE IF NOT EXISTS meta (\n    key TEXT PRIMARY KEY,\n    value TEXT NOT NULL\n);\n-- GTFS：车站（含 WGS84 坐标）\nCREATE TABLE IF NOT EXISTS g_stop (\n    stop_id TEXT PRIMARY KEY,\n    name    TEXT NOT NULL,\n    lat     REAL,\n    lon     REAL\n);\nCREATE INDEX IF NOT EXISTS ix_g_stop_name ON g_stop(name);\n-- GTFS：车次（DUMMY_* 为线路级占位，做时刻回答时必须过滤）\nCREATE TABLE IF NOT EXISTS g_trip (\n    trip_id   TEXT PRIMARY KEY,\n    route_id  TEXT,\n    short_name TEXT,\n    is_dummy  INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS ix_g_trip_short ON g_trip(short_name);\n-- GTFS：站序（含累计里程）\nCREATE TABLE IF NOT EXISTS g_stop_time (\n    trip_id   TEXT NOT NULL,\n    seq       INTEGER NOT NULL,\n    stop_id   TEXT NOT NULL,\n    arr       TEXT,\n    dep       TEXT,\n    dist      REAL,\n    PRIMARY KEY (trip_id, seq)\n);\nCREATE INDEX IF NOT EXISTS ix_g_stop_time_stop ON g_stop_time(stop_id);\n-- jprailfan：线路汇总（线路名 / 起终站 / 里程 / 备注）\nCREATE TABLE IF NOT EXISTS line_master (\n    line       TEXT PRIMARY KEY,\n    from_station TEXT,\n    to_station   TEXT,\n    mileage_km   REAL,\n    remark       TEXT,\n    fetched_at   TEXT\n);\n-- jprailfan：线路逐站里程表（按需抓取后缓存）\nCREATE TABLE IF NOT EXISTS line_station (\n    line          TEXT NOT NULL,\n    seq           INTEGER NOT NULL,\n    station       TEXT,\n    pinyin        TEXT,\n    telecode      TEXT,\n    tmjs_no       TEXT,\n    bureau        TEXT,\n    region        TEXT,\n    dist_from_start TEXT,\n    dist_adjacent   TEXT,\n    is_settlement   TEXT,\n    settlement_lines TEXT,\n    restriction     TEXT,\n    is_connector    INTEGER NOT NULL DEFAULT 0,\n    fetched_at      TEXT,\n    PRIMARY KEY (line, seq)\n);\n-- jprailfan：车站档案\nCREATE TABLE IF NOT EXISTS station_profile (\n    station    TEXT PRIMARY KEY,\n    pinyin     TEXT,\n    telecode   TEXT,\n    tmjs_no    TEXT,\n    bureau     TEXT,\n    is_settlement TEXT,\n    region     TEXT,\n    restriction   TEXT,\n    phone_area    TEXT,\n    raw_json      TEXT,\n    fetched_at    TEXT\n);\n'

from app.data.published_fares import SCHEMA as FARE_SCHEMA
SCHEMA += "\n" + FARE_SCHEMA

from app.data.photo_spots import SCHEMA as PHOTO_SCHEMA
SCHEMA += "\n" + PHOTO_SCHEMA
